class P2D16PerformanceFlowTests extends P1FlowTestSupport {
    @Autowired PerformanceTestPlanService plans;
    @Autowired PerformanceSyncService sync;
    @Autowired PerformanceTransferService transfer;
    @Autowired PerformanceTestExecutionService executions;
    @Autowired PerformanceTestExecutionRepository executionRows;
    record F(PlatformUserPrincipal actor,String project) { }
    F fixture(){var a=actor();return new F(a,project(a));}
    static final List<String> INTS=List.of("threadCount","rampUpSeconds","durationSeconds","stepCount","stepIntervalSeconds","targetTps","p95ThresholdMillis","expectedStatusCode","rendezvousUsers");
    Map<String,Object> group(String field){var g=new LinkedHashMap<String,Object>();g.put("name","Group");g.put("targetUrl","https://qa.example.test/qa");g.put("loadModel","RAMP_UP");g.put("threadCount",10);g.put("rampUpSeconds",0);g.put("durationSeconds",10);g.put("targetTps",10);g.put("p95ThresholdMillis",10);g.put("errorThresholdPercent",new java.math.BigDecimal("2.50"));g.put("requestMethod","POST");g.put("requestHeaders",Map.of());g.put("queryParameters",Map.of());g.put("requestBody","{}");g.put("expectedStatusCode",200);g.put("responseContains","ok");g.put("dataSetCsv",null);g.put("rendezvousUsers",null);
        if(field.equals("stepCount")||field.equals("stepIntervalSeconds")){g.put("loadModel","STEPPED_RAMP");g.put("threadCount",100000);g.put("stepCount",2);g.put("stepIntervalSeconds",1);g.put("targetTps",100000);}return g;}
    Map<String,Object> definition(Map<String,Object> g){var p=new LinkedHashMap<String,Object>();p.put("name",unique());p.put("description","");p.put("status","READY");p.put("threadGroups",List.of(g));return p;}
    String raw(String f,String token)throws Exception{var g=group(f);g.put(f,"RAW_TOKEN");return json.writeValueAsString(definition(g)).replace("\"RAW_TOKEN\"",token);}
    String base(F f){return "/api/v1/projects/"+f.project+"/performance/plans";}
    MvcResult submit(F f,String body)throws Exception{return mvc.perform(post(base(f)).with(user(f.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andReturn();}
    MvcResult edit(F f,String id,String body)throws Exception{return mvc.perform(put(base(f)+"/"+id).with(user(f.actor)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andReturn();}
    JsonNode data(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsString()).path("data");}
    void status(int expected,MvcResult r)throws Exception{assertEquals(expected,r.getResponse().getStatus(),r.getResponse().getContentAsString());}
    Map<String,Long> counts(){var r=new LinkedHashMap<String,Long>();for(String t:List.of("performance_test_plan","performance_test_thread_group","performance_test_execution","performance_test_execution_manifest","performance_runner_outbox","performance_transfer_receipt","performance_sync_receipt","audit_log"))r.put(t,jdbc.sql("SELECT COUNT(*) FROM "+t).query(Long.class).single());return r;}
    void bad(F f,String field,String token)throws Exception{var b=counts();status(400,submit(f,raw(field,token)));assertEquals(b,counts());}
    void rejected(Runnable r){assertEquals(400,assertThrows(ResponseStatusException.class,r::run).getStatusCode().value());}
    PerformanceTestPlanDetail create(F f)throws Exception {var r=submit(f,json.writeValueAsString(definition(group(""))));status(200,r);return plans.detail(f.actor,f.project,data(r).path("id").asText());}
    void good(F f,Map<String,Object> g)throws Exception{status(200,submit(f,json.writeValueAsString(definition(g))));}
    void badGroup(F f,Map<String,Object> g)throws Exception{var b=counts();status(400,submit(f,json.writeValueAsString(definition(g))));assertEquals(b,counts());}
    void exact(String field)throws Exception{var f=fixture();String n=field.equals("expectedStatusCode")?"200":"10";for(String t:List.of(n,n+".0",n+"e0")){var r=submit(f,raw(field,t));status(200,r);assertEquals(Integer.parseInt(n),data(r).path("threadGroups").get(0).path(field).asInt());}}
    void boundary(String field,int min,int max)throws Exception{var f=fixture();for(int n:List.of(min,max)){if(field.equals("stepIntervalSeconds")&&n==86400){bad(f,field,"86400");continue;}status(200,submit(f,raw(field,Integer.toString(n))));}bad(f,field,Integer.toString(min-1));bad(f,field,Integer.toString(max+1));if(field.equals("stepCount")){var g=group(field);g.put("threadCount",3);g.put("stepCount",4);badGroup(f,g);}}
    PerformanceSyncService.Request request(F source,F target){var items=sync.snapshot(source.actor,source.project,source.actor.userId()).items();return new PerformanceSyncService.Request(UUID.randomUUID().toString(),target.actor.userId(),sync.snapshot(target.actor,target.project,target.actor.userId()).revision(),items.stream().map(x->new PerformanceSyncService.Operation(UUID.randomUUID().toString(),x)).toList());}
    F exchangeSource()throws Exception{var f=fixture();var g=group("");g.put("rendezvousUsers",2);good(f,g);good(f,group("stepCount"));return f;}
    String equivalent(String raw,int kind){if(kind==0)return raw;String pattern="(\"(?:"+String.join("|",INTS)+")\":)([0-9]+)";return raw.replaceAll(pattern,"$1$2"+(kind==1?".0":"e0"));}
    List<String> invalidPayloads(String original){var result=new ArrayList<String>();for(String field:INTS)for(String token:List.of("1.5","1.0000000000000001","\"10\"","true")){String r=original.replaceAll("\""+field+"\":[0-9]+","\""+field+"\":"+token);assertNotEquals(original,r,field);result.add(r);}
        result.add(original.replace("\"errorThresholdPercent\":2.50","\"errorThresholdPercent\":\"2.50\""));
        for(String field:List.of("requestHeaders","queryParameters"))for(String t:List.of("1","true","[]","{}")){String r=original.replaceAll("\""+field+"\":\\{[^}]*\\}","\""+field+"\":{\"X-Code\":"+t+"}");assertNotEquals(original,r);result.add(r);}
        for(String field:List.of("requestBody","responseContains","dataSetCsv"))for(String t:List.of("1","true","{}")){String old=field.equals("dataSetCsv")?"null":field.equals("requestBody")?"\"{}\"":"\"ok\"";String r=original.replace("\""+field+"\":"+old,"\""+field+"\":"+t);assertNotEquals(original,r);result.add(r);}return result;}

    @Test @DisplayName("TC-D16PERF-01") void threadCountExact()throws Exception{exact("threadCount");}
    @Test @DisplayName("TC-D16PERF-02") void rampUpSecondsExact()throws Exception{exact("rampUpSeconds");}
    @Test @DisplayName("TC-D16PERF-03") void durationSecondsExact()throws Exception{exact("durationSeconds");}
    @Test @DisplayName("TC-D16PERF-04") void stepCountExact()throws Exception{exact("stepCount");}
    @Test @DisplayName("TC-D16PERF-05") void stepIntervalSecondsExact()throws Exception{exact("stepIntervalSeconds");}
    @Test @DisplayName("TC-D16PERF-06") void targetTpsExact()throws Exception{exact("targetTps");}
    @Test @DisplayName("TC-D16PERF-07") void p95ThresholdMillisExact()throws Exception{exact("p95ThresholdMillis");}
    @Test @DisplayName("TC-D16PERF-08") void expectedStatusCodeExact()throws Exception{exact("expectedStatusCode");}
    @Test @DisplayName("TC-D16PERF-09") void rendezvousUsersExact()throws Exception{exact("rendezvousUsers");}
    @Test @DisplayName("TC-D16PERF-10") void threadCountBoundary()throws Exception{boundary("threadCount",1,100000);}
    @Test @DisplayName("TC-D16PERF-11") void rampUpSecondsBoundary()throws Exception{boundary("rampUpSeconds",0,86400);}
    @Test @DisplayName("TC-D16PERF-12") void durationSecondsBoundary()throws Exception{boundary("durationSeconds",10,86400);}
    @Test @DisplayName("TC-D16PERF-13") void stepCountBoundary()throws Exception{boundary("stepCount",2,20);}
    @Test @DisplayName("TC-D16PERF-14") void stepIntervalSecondsBoundary()throws Exception{boundary("stepIntervalSeconds",1,86400);}
    @Test @DisplayName("TC-D16PERF-15") void targetTpsBoundary()throws Exception{boundary("targetTps",1,1000000);}
    @Test @DisplayName("TC-D16PERF-16") void p95ThresholdMillisBoundary()throws Exception{boundary("p95ThresholdMillis",1,600000);}
    @Test @DisplayName("TC-D16PERF-17") void expectedStatusCodeBoundary()throws Exception{boundary("expectedStatusCode",100,599);}
    @Test @DisplayName("TC-D16PERF-18") void rendezvousUsersBoundary()throws Exception{boundary("rendezvousUsers",2,10);}
    @Test @DisplayName("TC-D16PERF-19") void fractions()throws Exception{var f=fixture();for(String field:INTS)for(String t:List.of("1.5","1.0000000000000001"))bad(f,field,t);}
    @Test @DisplayName("TC-D16PERF-20") void numericStrings()throws Exception{var f=fixture();for(String field:INTS)for(String t:List.of("\"10\"","\" 10 \""))bad(f,field,t);}
    @Test @DisplayName("TC-D16PERF-21") void wrongTypes()throws Exception{var f=fixture();for(String field:INTS)for(String t:List.of("true","[]","{}"))bad(f,field,t);}
    @Test @DisplayName("TC-D16PERF-22") void overflow()throws Exception{var f=fixture();for(String field:INTS)for(String t:List.of("18446744073709551616","1e10000","NaN","Infinity","-Infinity"))bad(f,field,t);}
    @Test @DisplayName("TC-D16PERF-23") void requiredNull()throws Exception{var f=fixture();for(String field:List.of("threadCount","rampUpSeconds","durationSeconds")){bad(f,field,"null");var g=group(field);g.remove(field);badGroup(f,g);}}
    @Test @DisplayName("TC-D16PERF-24") void optionalNull()throws Exception{var f=fixture();for(boolean missing:List.of(true,false)){var g=group("");for(String field:List.of("targetTps","p95ThresholdMillis","expectedStatusCode","rendezvousUsers","errorThresholdPercent","stepCount","stepIntervalSeconds")){if(missing)g.remove(field);else g.put(field,null);}var r=submit(f,json.writeValueAsString(definition(g)));status(200,r);assertTrue(data(r).path("threadGroups").get(0).path("targetTps").isNull());}}
    @Test @DisplayName("TC-D16PERF-25") void steppedRequired()throws Exception{var f=fixture();for(String field:List.of("stepCount","stepIntervalSeconds")){var g=group("stepCount");g.put(field,null);badGroup(f,g);g.remove(field);badGroup(f,g);}}
    @Test @DisplayName("TC-D16PERF-26") void nonSteppedFields()throws Exception{var f=fixture();for(String model:List.of("RAMP_UP","STEADY"))for(String field:List.of("stepCount","stepIntervalSeconds")){var g=group("");g.put("loadModel",model);g.put(field,2);badGroup(f,g);}}
    @Test @DisplayName("TC-D16PERF-27") void steppedDuration()throws Exception{var f=fixture();var g=group("stepCount");g.put("stepCount",2);g.put("stepIntervalSeconds",86390);good(f,g);g.put("stepIntervalSeconds",86391);badGroup(f,g);}
    @Test @DisplayName("TC-D16PERF-28") void steppedTps()throws Exception{var f=fixture();var g=group("stepCount");g.put("targetTps",2);good(f,g);g.put("targetTps",1);badGroup(f,g);}
    @Test @DisplayName("TC-D16PERF-29") void steppedMutualExclusion()throws Exception{var f=fixture();var g=group("stepCount");g.put("rampUpSeconds",1);badGroup(f,g);g.put("rampUpSeconds",0);g.put("rendezvousUsers",2);badGroup(f,g);}
    @Test @DisplayName("TC-D16PERF-30") void decimalValid()throws Exception{var f=fixture();for(String token:List.of("2.50","2.5","25e-1")){var r=submit(f,raw("errorThresholdPercent",token));status(200,r);assertEquals(0,data(r).path("threadGroups").get(0).path("errorThresholdPercent").decimalValue().compareTo(new java.math.BigDecimal("2.50")));}}
    @Test @DisplayName("TC-D16PERF-31") void decimalPrecision()throws Exception{var f=fixture();for(String token:List.of("2.501","2.500","0.0000000000000001"))bad(f,"errorThresholdPercent",token);}
    @Test @DisplayName("TC-D16PERF-32") void decimalBoundary()throws Exception{var f=fixture();for(String t:List.of("0","100"))status(200,submit(f,raw("errorThresholdPercent",t)));for(String t:List.of("-0.01","100.01"))bad(f,"errorThresholdPercent",t);}
    @Test @DisplayName("TC-D16PERF-33") void decimalTypes()throws Exception{var f=fixture();for(String t:List.of("\"2.50\"","true","[]","{}","NaN","Infinity"))bad(f,"errorThresholdPercent",t);}
    @Test @DisplayName("TC-D16PERF-34") void decimalNull()throws Exception{var f=fixture();for(boolean missing:List.of(true,false)){var g=group("");if(missing)g.remove("errorThresholdPercent");else g.put("errorThresholdPercent",null);var r=submit(f,json.writeValueAsString(definition(g)));status(200,r);assertTrue(data(r).path("threadGroups").get(0).path("errorThresholdPercent").isNull());}}
    @Test @DisplayName("TC-D16PERF-35") void headerStrings()throws Exception{var f=fixture();var r=submit(f,raw("requestHeaders","{\"X-Code\":\"001\",\"X-Flag\":\"false\",\"X-Null\":\"null\"}"));status(200,r);assertEquals("001",data(r).path("threadGroups").get(0).path("requestHeaders").path("X-Code").asText());}
    @Test @DisplayName("TC-D16PERF-36") void queryStrings()throws Exception{var f=fixture();var r=submit(f,raw("queryParameters","{\"id\":\"001\",\"flag\":\"false\",\"literal\":\"null\",\"blank\":\"\"}"));status(200,r);assertEquals("001",data(r).path("threadGroups").get(0).path("queryParameters").path("id").asText());}
    @Test @DisplayName("TC-D16PERF-37") void bodyStrings()throws Exception{var f=fixture();var g=group("");g.put("requestBody","{\"n\":1}");good(f,g);g.put("requestMethod","GET");badGroup(f,g);}
    @Test @DisplayName("TC-D16PERF-38") void containsStrings()throws Exception{var f=fixture();var r=submit(f,raw("responseContains","\" 001 \""));status(200,r);assertEquals("001",data(r).path("threadGroups").get(0).path("responseContains").asText());}
    @Test @DisplayName("TC-D16PERF-39") void csvStrings()throws Exception{var f=fixture();var g=group("");g.put("dataSetCsv","id,name\r\n001,false");g.put("requestBody","${id}");var r=submit(f,json.writeValueAsString(definition(g)));status(200,r);assertEquals("id,name\n001,false",data(r).path("threadGroups").get(0).path("dataSetCsv").asText());}
    @Test @DisplayName("TC-D16PERF-40") void mapTypes()throws Exception{var f=fixture();for(String field:List.of("requestHeaders","queryParameters"))for(String t:List.of("1","true","[]","{}"))bad(f,field,"{\"X-Code\":"+t+"}");}
    @Test @DisplayName("TC-D16PERF-41") void textTypes()throws Exception{var f=fixture();for(String field:List.of("requestBody","responseContains","dataSetCsv"))for(String t:List.of("1","true","[]","{}"))bad(f,field,t);}
    @Test @DisplayName("TC-D16PERF-42") void textNull()throws Exception{var f=fixture();var g=group("");for(String field:List.of("requestBody","responseContains","dataSetCsv"))g.put(field,null);g.put("requestHeaders",Collections.singletonMap("X-Null",null));g.put("queryParameters",Collections.singletonMap("id",null));var r=submit(f,json.writeValueAsString(definition(g)));status(200,r);assertEquals("",data(r).path("threadGroups").get(0).path("requestHeaders").path("X-Null").asText());assertTrue(data(r).path("threadGroups").get(0).path("requestBody").isNull());}
    @Test @DisplayName("TC-D16PERF-43") void editValid()throws Exception{var f=fixture();var p=create(f);var x=executions.create(f.actor,f.project,p.id(),60);var frozen=executionRows.findManifest(f.project,x.id()).orElseThrow();var r=edit(f,p.id(),"{\"expectedVersion\":1,\"plan\":"+raw("threadCount","20.0")+"}");status(200,r);assertEquals(2,data(r).path("version").asInt());assertEquals(frozen,executionRows.findManifest(f.project,x.id()).orElseThrow());}
    @Test @DisplayName("TC-D16PERF-44") void editInvalid()throws Exception{var f=fixture();var p=create(f);var before=counts();status(400,edit(f,p.id(),"{\"expectedVersion\":1,\"plan\":"+raw("threadCount","1.5")+"}"));assertEquals(p,plans.detail(f.actor,f.project,p.id()));assertEquals(before,counts());}
    @Test @DisplayName("TC-D16PERF-45") void multiGroupAtomic()throws Exception{var f=fixture();var g=group("");g.put("name","Second");g.put("threadCount","RAW_TOKEN");var d=definition(group(""));d.put("threadGroups",List.of(group(""),g));var b=counts();status(400,submit(f,json.writeValueAsString(d).replace("\"RAW_TOKEN\"","1.5")));assertEquals(b,counts());}
    @Test @DisplayName("TC-D16PERF-46") void transferValid()throws Exception{var source=exchangeSource();for(int n=0;n<3;n++){var target=fixture();String raw=equivalent(json.writeValueAsString(new PerformanceTransferService.ImportRequest(UUID.randomUUID().toString(),target.actor.userId(),transfer.export(source.actor,source.project))),n);var receipt=transfer.transfer(target.actor,target.project,transfer.decode(raw.getBytes(StandardCharsets.UTF_8)));assertEquals(2,receipt.plans());assertTrue(plans.list(target.actor,target.project).stream().allMatch(p->p.status().equals("DRAFT")));}}
    @Test @DisplayName("TC-D16PERF-47") void transferInvalid()throws Exception{var source=exchangeSource();var target=fixture();String raw=json.writeValueAsString(new PerformanceTransferService.ImportRequest(UUID.randomUUID().toString(),target.actor.userId(),transfer.export(source.actor,source.project)));for(String value:invalidPayloads(raw)){var before=counts();rejected(()->transfer.transfer(target.actor,target.project,transfer.decode(value.getBytes(StandardCharsets.UTF_8))));assertEquals(before,counts());}}
    @Test @DisplayName("TC-D16PERF-48") void syncValid()throws Exception{var source=exchangeSource();for(int n=0;n<3;n++){var target=fixture();String raw=equivalent(json.writeValueAsString(request(source,target)),n);assertEquals(2,sync.apply(target.actor,target.project,sync.decode(raw.getBytes(StandardCharsets.UTF_8))).results().size());}}
    @Test @DisplayName("TC-D16PERF-49") void syncInvalid()throws Exception{var source=exchangeSource();var target=fixture();String raw=json.writeValueAsString(request(source,target));for(String value:invalidPayloads(raw)){var before=counts();rejected(()->sync.apply(target.actor,target.project,sync.decode(value.getBytes(StandardCharsets.UTF_8))));assertEquals(before,counts());}}
    @Test @DisplayName("TC-D16PERF-50") void oldReadOnly()throws Exception{var f=fixture();var p=create(f);var x=executions.create(f.actor,f.project,p.id(),60);var frozen=executionRows.findManifest(f.project,x.id()).orElseThrow();var before=counts();assertEquals(p,plans.detail(f.actor,f.project,p.id()));transfer.export(f.actor,f.project);sync.snapshot(f.actor,f.project,f.actor.userId());assertEquals(before,counts());assertEquals(frozen,executionRows.findManifest(f.project,x.id()).orElseThrow());}
    @Test @DisplayName("TC-D16PERF-51") void oldInvalidQueue()throws Exception{var f=fixture();var p=create(f);var x=executions.create(f.actor,f.project,p.id(),60);var frozen=executionRows.findManifest(f.project,x.id()).orElseThrow();jdbc.sql("UPDATE performance_test_thread_group SET thread_count=0 WHERE plan_id=:p").param("p",p.id()).update();var before=counts();rejected(()->executions.create(f.actor,f.project,p.id(),60));assertEquals(before,counts());jdbc.sql("UPDATE performance_test_thread_group SET thread_count=10,query_parameters=:q WHERE plan_id=:p").param("q","{\"id\":123}").param("p",p.id()).update();assertEquals("123",plans.detail(f.actor,f.project,p.id()).threadGroups().getFirst().queryParameters().get("id"));rejected(()->executions.create(f.actor,f.project,p.id(),60));assertEquals(before,counts());assertEquals(frozen,executionRows.findManifest(f.project,x.id()).orElseThrow());}
    @Test @DisplayName("TC-D16PERF-52") void permission()throws Exception{var f=fixture();var other=actor();var before=counts();var r=mvc.perform(post(base(f)).with(user(other)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(raw("threadCount","10"))).andReturn();status(403,r);assertEquals(before,counts());}
    @Test @DisplayName("TC-D16PERF-53") void versionConflict()throws Exception{var f=fixture();var p=create(f);var before=counts();for(String prefix:List.of("{}","{\"expectedVersion\":null}","{\"expectedVersion\":2}")){var d=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(prefix);d.set("plan",json.readTree(raw("threadCount","20")));status(prefix.contains(":2")?409:400,edit(f,p.id(),json.writeValueAsString(d)));}assertEquals(before,counts());}
    @Test @DisplayName("TC-D16PERF-54") void syncConflict()throws Exception{var source=exchangeSource();var target=fixture();var r=request(source,target);create(target);var before=counts();assertEquals(409,assertThrows(ResponseStatusException.class,()->sync.apply(target.actor,target.project,r)).getStatusCode().value());assertEquals(before,counts());}
    @Test @DisplayName("TC-D16PERF-55") void replay()throws Exception{var source=exchangeSource();var target=fixture();var r=request(source,target);var receipt=sync.apply(target.actor,target.project,r);var before=counts();assertEquals(receipt,sync.apply(target.actor,target.project,r));assertEquals(before,counts());var other=fixture();var tr=new PerformanceTransferService.ImportRequest(UUID.randomUUID().toString(),other.actor.userId(),transfer.export(source.actor,source.project));var got=transfer.transfer(other.actor,other.project,tr);before=counts();assertEquals(got,transfer.transfer(other.actor,other.project,tr));assertEquals(before,counts());}
    @Test @DisplayName("TC-D16PERF-56") void errorLocation()throws Exception{var f=fixture();var r=submit(f,raw("threadCount","\"D16_PRIVATE_MARKER\""));status(400,r);var b=json.readTree(r.getResponse().getContentAsString());assertTrue(b.path("details").has("threadGroups[0].threadCount"));assertFalse(b.toString().contains("D16_PRIVATE_MARKER"));var g=group("");g.put("name","Second");g.put("queryParameters",Map.of("D16_PRIVATE_KEY",true));var d=definition(group(""));d.put("threadGroups",List.of(group(""),g));r=submit(f,json.writeValueAsString(d));status(400,r);b=json.readTree(r.getResponse().getContentAsString());assertTrue(b.path("details").has("threadGroups[1].queryParameters"));assertFalse(b.toString().contains("D16_PRIVATE_KEY"));}
}
